def _read_owner_only_bytes(
    path: Path,
    *,
    blocker_prefix: str,
    maximum_size: int = 100_000,
    allow_group_world_read: bool = False,
    allow_empty: bool = False,
) -> bytes:
    """Read immutable evidence without following a symlink."""

    require(path.is_absolute(), f"{blocker_prefix}_path_not_absolute")
    flags = os.O_RDONLY | os.O_CLOEXEC
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise ProofFailure(f"{blocker_prefix}_open_failed") from exc
    try:
        metadata = os.fstat(descriptor)
        require(stat.S_ISREG(metadata.st_mode), f"{blocker_prefix}_not_regular")
        require(metadata.st_uid == os.getuid(), f"{blocker_prefix}_owner_mismatch")
        if allow_group_world_read:
            require(
                metadata.st_mode & 0o033 == 0,
                f"{blocker_prefix}_permissions_too_broad",
            )
        else:
            require(
                metadata.st_mode & 0o077 == 0,
                f"{blocker_prefix}_permissions_too_broad",
            )
        require(
            (allow_empty or metadata.st_size > 0)
            and metadata.st_size <= maximum_size,
            f"{blocker_prefix}_size_invalid",
        )
        raw = os.read(descriptor, maximum_size + 1)
    finally:
        os.close(descriptor)
    require(
        (allow_empty or len(raw) > 0) and len(raw) <= maximum_size,
        f"{blocker_prefix}_size_invalid",
    )
    return raw


def _decode_predecessor_json(
    raw: bytes,
    *,
    blocker: str,
) -> dict[str, Any]:
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ProofFailure(blocker) from exc
    require(isinstance(value, dict), blocker)
    return dict(value)


def _predecessor_exact_root_tuple(
    predecessor_plan: Mapping[str, Any],
) -> dict[str, Any]:
    roots = [
        object_record(item)
        for item in list_value(predecessor_plan.get("roots"))
    ]
    require(len(roots) == BATCH_SIZE, "predecessor_plan_root_count_mismatch")
    root = roots[0]
    order = object_record(root.get("order"))
    approvals = object_record(root.get("proof_approval_ids"))
    return {
        "approval_id": str(approvals.get("root_place") or ""),
        "batch_id": PREDECESSOR_BATCH_ID,
        "batch_slot": 1,
        "operator_intent": INTENTIONAL_FILL_OPERATOR_INTENT,
        "portfolio_id": str(predecessor_plan.get("portfolio_id") or ""),
        "portfolio_label": PROFILE_LABEL,
        "client_order_id": CARRIED_ROOT_CLIENT_ORDER_ID,
        "product_id": PRODUCT_ID,
        "side": "BUY",
        "order_type": "LIMIT",
        "time_in_force": "FILL_OR_KILL",
        "base_size": str(order.get("base_size") or ""),
        "limit_price": str(order.get("limit_price") or ""),
        "post_only": False,
        "size_in_quote": False,
        "quote_size": None,
    }


def validate_predecessor_artifacts(
    *,
    plan_raw: bytes,
    marker_raw: bytes,
    ledger_raw: bytes,
    sentinel_raw: bytes,
    cleanup_raw: bytes,
) -> dict[str, Any]:
    """Validate old bytes with their old runner/commit semantics exactly."""

    for raw, expected, blocker in (
        (plan_raw, PREDECESSOR_PLAN_BYTES_SHA256, "predecessor_plan_bytes_changed"),
        (
            marker_raw,
            PREDECESSOR_MARKER_BYTES_SHA256,
            "predecessor_marker_bytes_changed",
        ),
        (
            ledger_raw,
            PREDECESSOR_LEDGER_BYTES_SHA256,
            "predecessor_ledger_bytes_changed",
        ),
        (
            sentinel_raw,
            PREDECESSOR_SENTINEL_BYTES_SHA256,
            "predecessor_sentinel_bytes_changed",
        ),
        (
            cleanup_raw,
            PREDECESSOR_CLEANUP_BYTES_SHA256,
            "predecessor_cleanup_bytes_changed",
        ),
    ):
        require(hashlib.sha256(raw).hexdigest() == expected, blocker)
    predecessor_plan = _decode_predecessor_json(
        plan_raw,
        blocker="predecessor_plan_malformed",
    )
    marker = _decode_predecessor_json(
        marker_raw,
        blocker="predecessor_marker_malformed",
    )
    sentinel = _decode_predecessor_json(
        sentinel_raw,
        blocker="predecessor_sentinel_malformed",
    )
    cleanup = _decode_predecessor_json(
        cleanup_raw,
        blocker="predecessor_cleanup_malformed",
    )
    try:
        ledger_lines = ledger_raw.decode("utf-8").splitlines()
    except UnicodeDecodeError as exc:
        raise ProofFailure("predecessor_ledger_not_utf8") from exc
    require(len(ledger_lines) == 1, "predecessor_ledger_record_count_mismatch")
    try:
        ledger_record = json.loads(ledger_lines[0])
    except json.JSONDecodeError as exc:
        raise ProofFailure("predecessor_ledger_malformed") from exc
    require(isinstance(ledger_record, dict), "predecessor_ledger_record_not_object")
    require(
        predecessor_plan.get("plan_sha256") == PREDECESSOR_PLAN_SHA256
        and plan_hash(predecessor_plan) == PREDECESSOR_PLAN_SHA256,
        "predecessor_plan_hash_mismatch",
    )
    require(
        predecessor_plan.get("backend_commit") == PREDECESSOR_BACKEND_COMMIT
        and predecessor_plan.get("runner_sha256") == PREDECESSOR_RUNNER_SHA256
        and predecessor_plan.get("approval_id") == PREDECESSOR_APPROVAL_ID
        and predecessor_plan.get("batch_id") == PREDECESSOR_BATCH_ID
        and predecessor_plan.get("batch_size") == BATCH_SIZE
        and predecessor_plan.get("portfolio_label") == PROFILE_LABEL
        and predecessor_plan.get("product_id") == PRODUCT_ID,
        "predecessor_plan_identity_mismatch",
    )
    roots = [
        object_record(item)
        for item in list_value(predecessor_plan.get("roots"))
    ]
    predecessor_root_ids = [
        str(root.get("root_client_order_id") or "") for root in roots
    ]
    predecessor_child_ids = [
        str(root.get("child_client_order_id") or "") for root in roots
    ]
    require(
        predecessor_root_ids == list(PREDECESSOR_PLANNED_ROOT_CLIENT_ORDER_IDS)
        and predecessor_child_ids
        == list(PREDECESSOR_PLANNED_CHILD_CLIENT_ORDER_IDS),
        "predecessor_planned_ids_mismatch",
    )
    carried_root = roots[0]
    require(
        carried_root.get("slot") == 1
        and carried_root.get("root_client_order_id")
        == CARRIED_ROOT_CLIENT_ORDER_ID
        and carried_root.get("child_client_order_id")
        == CARRIED_CHILD_CLIENT_ORDER_ID
        and object_record(carried_root.get("order")) == _carried_root_order()
        and carried_root.get("planned_notional_usdc")
        == decimal_text(CARRIED_ROOT_PLANNED_NOTIONAL)
        and deterministic_child_client_order_id(CARRIED_ROOT_CLIENT_ORDER_ID)
        == CARRIED_CHILD_CLIENT_ORDER_ID,
        "predecessor_carried_root_mismatch",
    )
    require(
        marker.get("authority") == "controlled-admin-spot-root-child-batch"
        and marker.get("plan_file") == str(PREDECESSOR_PLAN_PATH)
        and marker.get("plan_sha256") == PREDECESSOR_PLAN_SHA256
        and marker.get("runner_sha256") == PREDECESSOR_RUNNER_SHA256
        and marker.get("backend_commit") == PREDECESSOR_BACKEND_COMMIT
        and marker.get("approval_id") == PREDECESSOR_APPROVAL_ID
        and marker.get("batch_id") == PREDECESSOR_BATCH_ID
        and marker.get("attempt_ledger_path") == str(PREDECESSOR_LEDGER_PATH)
        and marker.get("marker_path") == str(PREDECESSOR_MARKER_PATH)
        and marker.get("root_order_maximum") == BATCH_SIZE
        and marker.get("child_order_maximum") == BATCH_SIZE,
        "predecessor_marker_binding_mismatch",
    )
    exact_root_tuples = [
        object_record(item)
        for item in list_value(marker.get("exact_root_tuples"))
    ]
    require(
        len(exact_root_tuples) == BATCH_SIZE
        and exact_root_tuples[0] == _predecessor_exact_root_tuple(predecessor_plan),
        "predecessor_marker_root_tuple_mismatch",
    )
    require(
        ledger_record.get("schema_version") == "1"
        and ledger_record.get("sequence") == 1
        and ledger_record.get("batch_id") == PREDECESSOR_BATCH_ID
        and ledger_record.get("batch_slot") == 1
        and ledger_record.get("attempt_kind") == "root"
        and ledger_record.get("client_order_id")
        == CARRIED_ROOT_CLIENT_ORDER_ID
        and ledger_record.get("root_client_order_id")
        == CARRIED_ROOT_CLIENT_ORDER_ID
        and ledger_record.get("plan_sha256") == PREDECESSOR_PLAN_SHA256
        and ledger_record.get("runner_sha256") == PREDECESSOR_RUNNER_SHA256
        and ledger_record.get("backend_commit") == PREDECESSOR_BACKEND_COMMIT
        and object_record(ledger_record.get("exact_order_tuple"))
        == _predecessor_exact_root_tuple(predecessor_plan)
        and ledger_record.get("exact_order_tuple_sha256")
        == _canonical_json_sha256(
            _predecessor_exact_root_tuple(predecessor_plan)
        ),
        "predecessor_ledger_root_record_mismatch",
    )
    require(
        sentinel.get("installed") is True
        and sentinel.get("wrapper_identity_proven") is True
        and sentinel.get("root_create_order_call_count") == 1
        and sentinel.get("child_place_limit_order_call_count") == 0
        and sentinel.get("root_sdk_inflight") is False
        and sentinel.get("child_sdk_inflight") is False
        and sentinel.get("denied_call_count") == 0
        and sentinel.get("critical_failure") is False
        and sentinel.get("phase") == "runtime_exited",
        "predecessor_sentinel_mismatch",
    )
    require(
        cleanup.get("live_service_disable_attempted") is True
        and cleanup.get("live_service_disable_proven_before_cleanup") is True
        and cleanup.get("live_service_disable_proven_after_cleanup") is True
        and cleanup.get("runtime_pid") == sentinel.get("process_id"),
        "predecessor_cleanup_service_disable_mismatch",
    )
    binding = offline_predecessor_binding_fixture()
    require(
        binding["portfolio_id"] == predecessor_plan.get("portfolio_id"),
        "predecessor_portfolio_mismatch",
    )
    return binding


def load_predecessor_binding() -> dict[str, Any]:
    """Read and validate predecessor evidence without writing any old path."""

    return validate_predecessor_artifacts(
        plan_raw=_read_owner_only_bytes(
            PREDECESSOR_PLAN_PATH,
            blocker_prefix="predecessor_plan",
        ),
        marker_raw=_read_owner_only_bytes(
            PREDECESSOR_MARKER_PATH,
            blocker_prefix="predecessor_marker",
        ),
        ledger_raw=_read_owner_only_bytes(
            PREDECESSOR_LEDGER_PATH,
            blocker_prefix="predecessor_ledger",
        ),
        sentinel_raw=_read_owner_only_bytes(
            PREDECESSOR_SENTINEL_PATH,
            blocker_prefix="predecessor_sentinel",
        ),
        cleanup_raw=_read_owner_only_bytes(
            PREDECESSOR_CLEANUP_PATH,
            blocker_prefix="predecessor_cleanup",
            allow_group_world_read=True,
        ),
    )


def validate_failed_successor_artifacts(
    *,
    plan_raw: bytes,
    marker_raw: bytes,
    ledger_raw: bytes,
    failure_raw: bytes,
    cleanup_raw: bytes,
    sentinel_raw: bytes,
    parent_loss_raw: bytes,
    runtime_auth_raw: bytes,
    runtime_auth_used_raw: bytes,
) -> dict[str, Any]:
    """Validate the failed v1's immutable zero-placement evidence exactly."""

    for raw, expected, blocker in (
        (
            plan_raw,
            FAILED_SUCCESSOR_V1_PLAN_BYTES_SHA256,
            "failed_successor_plan_bytes_changed",
        ),
        (
            marker_raw,
            FAILED_SUCCESSOR_V1_MARKER_BYTES_SHA256,
            "failed_successor_marker_bytes_changed",
        ),
        (
            ledger_raw,
            FAILED_SUCCESSOR_V1_LEDGER_BYTES_SHA256,
            "failed_successor_ledger_bytes_changed",
        ),
        (
            failure_raw,
            FAILED_SUCCESSOR_V1_FAILURE_BYTES_SHA256,
            "failed_successor_failure_bytes_changed",
        ),
        (
            cleanup_raw,
            FAILED_SUCCESSOR_V1_CLEANUP_BYTES_SHA256,
            "failed_successor_cleanup_bytes_changed",
        ),
        (
            sentinel_raw,
            FAILED_SUCCESSOR_V1_SENTINEL_BYTES_SHA256,
            "failed_successor_sentinel_bytes_changed",
        ),
        (
            parent_loss_raw,
            FAILED_SUCCESSOR_V1_PARENT_LOSS_BYTES_SHA256,
            "failed_successor_parent_loss_bytes_changed",
        ),
        (
            runtime_auth_raw,
            FAILED_SUCCESSOR_V1_RUNTIME_AUTH_BYTES_SHA256,
            "failed_successor_runtime_auth_bytes_changed",
        ),
        (
            runtime_auth_used_raw,
            FAILED_SUCCESSOR_V1_RUNTIME_AUTH_USED_BYTES_SHA256,
            "failed_successor_runtime_auth_used_bytes_changed",
        ),
    ):
        require(hashlib.sha256(raw).hexdigest() == expected, blocker)
    require(ledger_raw == b"", "failed_successor_attempt_ledger_not_empty")

    plan = _decode_predecessor_json(
        plan_raw,
        blocker="failed_successor_plan_malformed",
    )
    marker = _decode_predecessor_json(
        marker_raw,
        blocker="failed_successor_marker_malformed",
    )
    failure = _decode_predecessor_json(
        failure_raw,
        blocker="failed_successor_failure_malformed",
    )
    cleanup = _decode_predecessor_json(
        cleanup_raw,
        blocker="failed_successor_cleanup_malformed",
    )
    sentinel = _decode_predecessor_json(
        sentinel_raw,
        blocker="failed_successor_sentinel_malformed",
    )
    parent_loss = _decode_predecessor_json(
        parent_loss_raw,
        blocker="failed_successor_parent_loss_malformed",
    )
    runtime_auth = _decode_predecessor_json(
        runtime_auth_raw,
        blocker="failed_successor_runtime_auth_malformed",
    )
    runtime_auth_used = _decode_predecessor_json(
        runtime_auth_used_raw,
        blocker="failed_successor_runtime_auth_used_malformed",
    )

    require(
        plan.get("schema_version") == "5"
        and plan.get("continuation_kind")
        == "consumed_root_1_child_1_first_successor"
        and plan.get("backend_commit")
        == FAILED_SUCCESSOR_V1_PRODUCTION_PARENT_COMMIT
        and plan.get("runner_sha256") == FAILED_SUCCESSOR_V1_RUNNER_SHA256
        and plan.get("approval_id") == FAILED_SUCCESSOR_V1_APPROVAL_ID
        and plan.get("batch_id") == FAILED_SUCCESSOR_V1_BATCH_ID
        and plan.get("plan_sha256") == FAILED_SUCCESSOR_V1_PLAN_SHA256
        and plan_hash(plan) == FAILED_SUCCESSOR_V1_PLAN_SHA256
        and plan.get("remaining_attempt_count") == PRIOR_V8_ATTEMPT_COUNT
        and plan.get("new_root_order_maximum")
        == V8_ROOT_ORDER_MAXIMUM
        and plan.get("child_order_maximum")
        == PRIOR_V8_CHILD_ORDER_MAXIMUM
        and object_record(plan.get("predecessor_binding"))
        == offline_predecessor_binding_fixture(),
        "failed_successor_plan_identity_mismatch",
    )
    plan_roots = [
        object_record(root) for root in list_value(plan.get("roots"))
    ]
    require(
        [str(root.get("root_client_order_id") or "") for root in plan_roots]
        == list(FAILED_SUCCESSOR_V1_PLANNED_ROOT_CLIENT_ORDER_IDS)
        and [
            str(root.get("child_client_order_id") or "")
            for root in plan_roots
        ]
        == list(FAILED_SUCCESSOR_V1_PLANNED_CHILD_CLIENT_ORDER_IDS),
        "failed_successor_plan_ids_mismatch",
    )
    require(
        marker.get("schema_version") == "1"
        and marker.get("authority")
        == "controlled-admin-spot-root-child-successor-batch"
        and marker.get("backend_commit")
        == FAILED_SUCCESSOR_V1_PRODUCTION_PARENT_COMMIT
        and marker.get("runner_sha256")
        == FAILED_SUCCESSOR_V1_RUNNER_SHA256
        and marker.get("approval_id") == FAILED_SUCCESSOR_V1_APPROVAL_ID
        and marker.get("batch_id") == FAILED_SUCCESSOR_V1_BATCH_ID
        and marker.get("plan_sha256") == FAILED_SUCCESSOR_V1_PLAN_SHA256
        and marker.get("plan_file") == str(FAILED_SUCCESSOR_V1_PLAN_PATH)
        and marker.get("marker_path")
        == str(FAILED_SUCCESSOR_V1_MARKER_PATH)
        and marker.get("attempt_ledger_path")
        == str(FAILED_SUCCESSOR_V1_LEDGER_PATH)
        and marker.get("remaining_attempt_count")
        == PRIOR_V8_ATTEMPT_COUNT
        and marker.get("root_order_maximum")
        == V8_ROOT_ORDER_MAXIMUM
        and marker.get("child_order_maximum")
        == PRIOR_V8_CHILD_ORDER_MAXIMUM
        and marker.get("process_id") == FAILED_SUCCESSOR_V1_PARENT_PID
        and object_record(marker.get("predecessor_binding"))
        == offline_predecessor_binding_fixture()
        and marker.get("exact_child_client_order_ids")
        == list(FAILED_SUCCESSOR_V1_PLANNED_CHILD_CLIENT_ORDER_IDS),
        "failed_successor_marker_identity_mismatch",
    )
    failure_reconciliation = object_record(
        failure.get("failure_reconciliation")
    )
    require(
        failure.get("status") == "failed"
        and failure.get("failure_type") == "ProofFailure"
        and failure.get("failure_reason")
        == "fill_ledger_not_clean_ws_derived_before_reconciliation"
        and failure.get("backend_commit")
        == FAILED_SUCCESSOR_V1_PRODUCTION_PARENT_COMMIT
        and failure.get("runner_sha256")
        == FAILED_SUCCESSOR_V1_RUNNER_SHA256
        and failure.get("batch_id") == FAILED_SUCCESSOR_V1_BATCH_ID
        and failure.get("plan_sha256") == FAILED_SUCCESSOR_V1_PLAN_SHA256
        and failure.get("retry_authorized") is False
        and failure.get("substitution_authorized") is False
        and failure.get("generic_or_later_child_authorized") is False
        and failure_reconciliation.get("attempt_ledger_count") == 0
        and failure_reconciliation.get("attempt_ledger_readback_proven")
        is True
        and failure_reconciliation.get("current_root_attempt_count") == 0
        and failure_reconciliation.get("current_child_attempt_count") == 0
        and failure_reconciliation.get("current_root_attempt_consumed")
        is False
        and failure_reconciliation.get("current_child_attempt_consumed")
        is False
        and failure_reconciliation.get("current_root_sdk_call_occurred")
        is False
        and failure_reconciliation.get("current_child_sdk_call_occurred")
        is False
        and failure_reconciliation.get("authoritative_active_spot_order_count")
        == 0
        and failure_reconciliation.get("live_service_disabled") is True
        and failure_reconciliation.get("next_slot_authorized") is False,
        "failed_successor_failure_evidence_mismatch",
    )
    require(
        cleanup.get("runtime_pid") == FAILED_SUCCESSOR_V1_RUNTIME_PID
        and cleanup.get("runtime_process_started") is True
        and cleanup.get("runtime_preserved_for_reconciliation") is True
        and cleanup.get("runtime_process_shutdown_proven") is False
        and cleanup.get("live_service_disable_attempted") is True
        and cleanup.get("live_service_disable_proven_before_cleanup") is True
        and cleanup.get("live_service_disable_proven_after_cleanup") is True
        and cleanup.get("live_service_enable_attempted") is False,
        "failed_successor_cleanup_evidence_mismatch",
    )
    require(
        sentinel.get("process_id") == FAILED_SUCCESSOR_V1_RUNTIME_PID
        and sentinel.get("phase") == "runtime_exited"
        and sentinel.get("installed") is True
        and sentinel.get("wrapper_identity_proven") is True
        and sentinel.get("root_create_order_call_count") == 0
        and sentinel.get("child_place_limit_order_call_count") == 0
        and sentinel.get("root_sdk_inflight") is False
        and sentinel.get("child_sdk_inflight") is False
        and sentinel.get("denied_call_count") == 0
        and sentinel.get("critical_failure") is False
        and sentinel.get("error") is None,
        "failed_successor_final_sentinel_mismatch",
    )
    require(
        parent_loss.get("parent_pid") == FAILED_SUCCESSOR_V1_PARENT_PID
        and parent_loss.get("live_service_disable_proven") is True
        and parent_loss.get("new_sdk_placements_denied") is True
        and parent_loss.get("sdk_quiescence_proven") is True
        and parent_loss.get("root_create_order_call_count") == 0
        and parent_loss.get("child_place_limit_order_call_count") == 0
        and parent_loss.get("denied_sdk_call_count") == 0
        and parent_loss.get("root_sdk_inflight_after_wait") is False
        and parent_loss.get("child_sdk_inflight_after_wait") is False
        and parent_loss.get("authoritative_active_order_read_proven") is True
        and parent_loss.get("authoritative_active_orders_before_cancel") == []
        and parent_loss.get("authoritative_active_orders_after_reconciliation")
        == []
        and parent_loss.get("unknown_active_client_order_ids") == []
        and parent_loss.get("exact_active_client_order_ids") == []
        and parent_loss.get("authoritative_active_zero_after_reconciliation")
        is True
        and parent_loss.get("transmitted_attempt_count") == 0
        and parent_loss.get("terminal_transmitted_attempt_count") == 0
        and parent_loss.get("all_transmitted_attempts_terminal") is True
        and parent_loss.get("exact_transmitted_attempt_states") == {}
        and parent_loss.get("critical_attempt_failures") == {}
        and parent_loss.get("operator_reconciliation_required") is False
        and parent_loss.get("automatic_cancel_retry_authorized") is False,
        "failed_successor_parent_loss_evidence_mismatch",
    )
    for payload, blocker in (
        (runtime_auth, "failed_successor_runtime_auth_identity_mismatch"),
        (runtime_auth_used, "failed_successor_runtime_auth_used_identity_mismatch"),
    ):
        require(
            payload.get("approval_id") == FAILED_SUCCESSOR_V1_APPROVAL_ID
            and payload.get("batch_id") == FAILED_SUCCESSOR_V1_BATCH_ID
            and payload.get("plan_sha256") == FAILED_SUCCESSOR_V1_PLAN_SHA256
            and payload.get("runner_sha256")
            == FAILED_SUCCESSOR_V1_RUNNER_SHA256
            and payload.get("parent_pid") == FAILED_SUCCESSOR_V1_PARENT_PID
            and payload.get("attempt_ledger_path")
            == str(FAILED_SUCCESSOR_V1_LEDGER_PATH),
            blocker,
        )
    return offline_failed_successor_binding_fixture()


def load_failed_successor_binding() -> dict[str, Any]:
    """Read and validate every immutable failed-v1 authority artifact."""

    return validate_failed_successor_artifacts(
        plan_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_PLAN_PATH,
            blocker_prefix="failed_successor_plan",
        ),
        marker_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_MARKER_PATH,
            blocker_prefix="failed_successor_marker",
        ),
        ledger_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_LEDGER_PATH,
            blocker_prefix="failed_successor_ledger",
            allow_empty=True,
        ),
        failure_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_FAILURE_PATH,
            blocker_prefix="failed_successor_failure",
            allow_group_world_read=True,
        ),
        cleanup_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_CLEANUP_PATH,
            blocker_prefix="failed_successor_cleanup",
            allow_group_world_read=True,
        ),
        sentinel_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_SENTINEL_PATH,
            blocker_prefix="failed_successor_sentinel",
        ),
        parent_loss_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_PARENT_LOSS_PATH,
            blocker_prefix="failed_successor_parent_loss",
        ),
        runtime_auth_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_RUNTIME_AUTH_PATH,
            blocker_prefix="failed_successor_runtime_auth",
        ),
        runtime_auth_used_raw=_read_owner_only_bytes(
            FAILED_SUCCESSOR_V1_RUNTIME_AUTH_USED_PATH,
            blocker_prefix="failed_successor_runtime_auth_used",
        ),
    )


def validate_failed_v2_artifacts(
    *,
    plan_raw: bytes,
    marker_raw: bytes,
    ledger_raw: bytes,
    failure_raw: bytes,
    cleanup_raw: bytes,
    sentinel_raw: bytes,
    parent_loss_raw: bytes,
    runtime_auth_raw: bytes,
    runtime_auth_used_raw: bytes,
) -> dict[str, Any]:
    """Validate failed v2's one consumed but untransmitted child attempt."""

    for raw, expected, blocker in (
        (
            plan_raw,
            FAILED_SUCCESSOR_V2_PLAN_BYTES_SHA256,
            "failed_v2_plan_bytes_changed",
        ),
        (
            marker_raw,
            FAILED_SUCCESSOR_V2_MARKER_BYTES_SHA256,
            "failed_v2_marker_bytes_changed",
        ),
        (
            ledger_raw,
            FAILED_SUCCESSOR_V2_LEDGER_BYTES_SHA256,
            "failed_v2_ledger_bytes_changed",
        ),
        (
            failure_raw,
            FAILED_SUCCESSOR_V2_FAILURE_BYTES_SHA256,
            "failed_v2_failure_bytes_changed",
        ),
        (
            cleanup_raw,
            FAILED_SUCCESSOR_V2_CLEANUP_BYTES_SHA256,
            "failed_v2_cleanup_bytes_changed",
        ),
        (
            sentinel_raw,
            FAILED_SUCCESSOR_V2_SENTINEL_BYTES_SHA256,
            "failed_v2_sentinel_bytes_changed",
        ),
        (
            parent_loss_raw,
            FAILED_SUCCESSOR_V2_PARENT_LOSS_BYTES_SHA256,
            "failed_v2_parent_loss_bytes_changed",
        ),
        (
            runtime_auth_raw,
            FAILED_SUCCESSOR_V2_RUNTIME_AUTH_BYTES_SHA256,
            "failed_v2_runtime_auth_bytes_changed",
        ),
        (
            runtime_auth_used_raw,
            FAILED_SUCCESSOR_V2_RUNTIME_AUTH_USED_BYTES_SHA256,
            "failed_v2_runtime_auth_used_bytes_changed",
        ),
    ):
        require(hashlib.sha256(raw).hexdigest() == expected, blocker)

    plan = _decode_predecessor_json(
        plan_raw,
        blocker="failed_v2_plan_malformed",
    )
    marker = _decode_predecessor_json(
        marker_raw,
        blocker="failed_v2_marker_malformed",
    )
    failure = _decode_predecessor_json(
        failure_raw,
        blocker="failed_v2_failure_malformed",
    )
    cleanup = _decode_predecessor_json(
        cleanup_raw,
        blocker="failed_v2_cleanup_malformed",
    )
    sentinel = _decode_predecessor_json(
        sentinel_raw,
        blocker="failed_v2_sentinel_malformed",
    )
    parent_loss = _decode_predecessor_json(
        parent_loss_raw,
        blocker="failed_v2_parent_loss_malformed",
    )
    runtime_auth = _decode_predecessor_json(
        runtime_auth_raw,
        blocker="failed_v2_runtime_auth_malformed",
    )
    runtime_auth_used = _decode_predecessor_json(
        runtime_auth_used_raw,
        blocker="failed_v2_runtime_auth_used_malformed",
    )
    try:
        ledger_lines = ledger_raw.decode("utf-8").splitlines()
    except UnicodeDecodeError as exc:
        raise ProofFailure("failed_v2_ledger_not_utf8") from exc
    require(len(ledger_lines) == 1, "failed_v2_ledger_record_count_mismatch")
    try:
        ledger_record = json.loads(ledger_lines[0])
    except json.JSONDecodeError as exc:
        raise ProofFailure("failed_v2_ledger_malformed") from exc
    require(isinstance(ledger_record, dict), "failed_v2_ledger_record_not_object")

    require(
        plan.get("schema_version") == "6"
        and plan.get("continuation_kind")
        == "failed_successor_v1_child_1_first_v2"
        and plan.get("backend_commit")
        == FAILED_SUCCESSOR_V2_PRODUCTION_PARENT_COMMIT
        and plan.get("runner_sha256") == FAILED_SUCCESSOR_V2_RUNNER_SHA256
        and plan.get("approval_id") == FAILED_SUCCESSOR_V2_APPROVAL_ID
        and plan.get("batch_id") == FAILED_SUCCESSOR_V2_BATCH_ID
        and plan.get("plan_sha256") == FAILED_SUCCESSOR_V2_PLAN_SHA256
        and plan_hash(plan) == FAILED_SUCCESSOR_V2_PLAN_SHA256
        and plan.get("remaining_attempt_count") == PRIOR_V8_ATTEMPT_COUNT
        and plan.get("new_root_order_maximum")
        == V8_ROOT_ORDER_MAXIMUM
        and plan.get("child_order_maximum")
        == PRIOR_V8_CHILD_ORDER_MAXIMUM
        and object_record(plan.get("predecessor_binding"))
        == offline_predecessor_binding_fixture()
        and object_record(plan.get("failed_successor_binding"))
        == offline_failed_successor_binding_fixture(),
        "failed_v2_plan_identity_mismatch",
    )
    plan_roots = [
        object_record(root) for root in list_value(plan.get("roots"))
    ]
    require(
        [str(root.get("root_client_order_id") or "") for root in plan_roots]
        == list(FAILED_SUCCESSOR_V2_PLANNED_ROOT_CLIENT_ORDER_IDS)
        and [
            str(root.get("child_client_order_id") or "")
            for root in plan_roots
        ]
        == list(FAILED_SUCCESSOR_V2_PLANNED_CHILD_CLIENT_ORDER_IDS),
        "failed_v2_plan_ids_mismatch",
    )
    require(
        marker.get("schema_version") == "2"
        and marker.get("authority")
        == "controlled-admin-spot-root-child-successor-v2-batch"
        and marker.get("backend_commit")
        == FAILED_SUCCESSOR_V2_PRODUCTION_PARENT_COMMIT
        and marker.get("runner_sha256")
        == FAILED_SUCCESSOR_V2_RUNNER_SHA256
        and marker.get("approval_id") == FAILED_SUCCESSOR_V2_APPROVAL_ID
        and marker.get("batch_id") == FAILED_SUCCESSOR_V2_BATCH_ID
        and marker.get("plan_sha256") == FAILED_SUCCESSOR_V2_PLAN_SHA256
        and marker.get("plan_file") == str(FAILED_SUCCESSOR_V2_PLAN_PATH)
        and marker.get("marker_path") == str(FAILED_SUCCESSOR_V2_MARKER_PATH)
        and marker.get("attempt_ledger_path")
        == str(FAILED_SUCCESSOR_V2_LEDGER_PATH)
        and marker.get("remaining_attempt_count") == PRIOR_V8_ATTEMPT_COUNT
        and marker.get("root_order_maximum")
        == V8_ROOT_ORDER_MAXIMUM
        and marker.get("child_order_maximum")
        == PRIOR_V8_CHILD_ORDER_MAXIMUM
        and marker.get("process_id") == FAILED_SUCCESSOR_V2_PARENT_PID
        and object_record(marker.get("predecessor_binding"))
        == offline_predecessor_binding_fixture()
        and object_record(marker.get("failed_successor_binding"))
        == offline_failed_successor_binding_fixture()
        and marker.get("exact_child_client_order_ids")
        == list(FAILED_SUCCESSOR_V2_PLANNED_CHILD_CLIENT_ORDER_IDS),
        "failed_v2_marker_identity_mismatch",
    )
    carried_root = plan_roots[0]
    carried_approvals = object_record(carried_root.get("proof_approval_ids"))
    exact_tuple = object_record(ledger_record.get("exact_order_tuple"))
    require(
        ledger_record.get("schema_version") == "1"
        and ledger_record.get("sequence") == 1
        and ledger_record.get("attempt_kind") == "child"
        and ledger_record.get("batch_slot") == 1
        and ledger_record.get("client_order_id")
        == CARRIED_CHILD_CLIENT_ORDER_ID
        and ledger_record.get("root_client_order_id")
        == CARRIED_ROOT_CLIENT_ORDER_ID
        and ledger_record.get("backend_commit")
        == FAILED_SUCCESSOR_V2_PRODUCTION_PARENT_COMMIT
        and ledger_record.get("runner_sha256")
        == FAILED_SUCCESSOR_V2_RUNNER_SHA256
        and ledger_record.get("batch_id") == FAILED_SUCCESSOR_V2_BATCH_ID
        and ledger_record.get("plan_sha256") == FAILED_SUCCESSOR_V2_PLAN_SHA256
        and ledger_record.get("process_id") == FAILED_SUCCESSOR_V2_PARENT_PID
        and exact_tuple.get("approval_snapshot_id")
        == carried_approvals.get("child_reveal")
        and exact_tuple.get("batch_id") == FAILED_SUCCESSOR_V2_BATCH_ID
        and exact_tuple.get("batch_slot") == 1
        and exact_tuple.get("client_order_id")
        == CARRIED_CHILD_CLIENT_ORDER_ID
        and exact_tuple.get("root_client_order_id")
        == CARRIED_ROOT_CLIENT_ORDER_ID
        and exact_tuple.get("product_id") == PRODUCT_ID
        and exact_tuple.get("side") == "SELL"
        and exact_tuple.get("order_type") == "LIMIT"
        and exact_tuple.get("time_in_force") == "GOOD_UNTIL_CANCELLED"
        and exact_tuple.get("post_only") is False
        and exact_tuple.get("base_size")
        == decimal_text(CARRIED_ROOT_FILLED_SIZE)
        and exact_tuple.get("minimum_bid_ratio")
        == decimal_text(CHILD_MINIMUM_BID_RATIO)
        and exact_tuple.get("strict_max_notional_usdc")
        == decimal_text(CHILD_SUBMITTED_CAP)
        and ledger_record.get("exact_order_tuple_sha256")
        == FAILED_SUCCESSOR_V2_CONSUMED_CHILD_TUPLE_SHA256
        == _canonical_json_sha256(exact_tuple),
        "failed_v2_consumed_child_attempt_mismatch",
    )
    failure_reconciliation = object_record(failure.get("failure_reconciliation"))
    slot_results = [
        object_record(row) for row in list_value(failure.get("slot_results"))
    ]
    require(
        failure.get("status") == "failed"
        and failure.get("failure_type") == "ProofFailure"
        and failure.get("failure_reason") == "child_reveal_http_failed:400"
        and failure.get("backend_commit")
        == FAILED_SUCCESSOR_V2_PRODUCTION_PARENT_COMMIT
        and failure.get("runner_sha256") == FAILED_SUCCESSOR_V2_RUNNER_SHA256
        and failure.get("batch_id") == FAILED_SUCCESSOR_V2_BATCH_ID
        and failure.get("plan_sha256") == FAILED_SUCCESSOR_V2_PLAN_SHA256
        and failure.get("retry_authorized") is False
        and failure.get("substitution_authorized") is False
        and failure.get("generic_or_later_child_authorized") is False
        and failure.get("single_child_failure_cancel_attempted") is True
        and failure_reconciliation.get("attempt_ledger_count") == 1
        and failure_reconciliation.get("attempt_ledger_readback_proven")
        is True
        and failure_reconciliation.get("current_root_attempt_count") == 0
        and failure_reconciliation.get("current_child_attempt_count") == 1
        and failure_reconciliation.get("current_root_attempt_consumed")
        is False
        and failure_reconciliation.get("current_child_attempt_consumed")
        is True
        and failure_reconciliation.get("current_root_sdk_call_occurred")
        is False
        and failure_reconciliation.get("current_child_sdk_call_occurred")
        is False
        and failure_reconciliation.get("authoritative_active_spot_order_count")
        == 0
        and failure_reconciliation.get("authoritative_active_spot_orders") == []
        and failure_reconciliation.get("live_service_disabled") is True
        and failure_reconciliation.get("next_slot_authorized") is False
        and len(slot_results) == 1
        and object_record(slot_results[0].get("child_attempt_ledger_record"))
        == ledger_record,
        "failed_v2_failure_evidence_mismatch",
    )
    require(
        cleanup.get("runtime_pid") == FAILED_SUCCESSOR_V2_RUNTIME_PID
        and cleanup.get("runtime_process_started") is True
        and cleanup.get("runtime_preserved_for_reconciliation") is True
        and cleanup.get("runtime_process_shutdown_proven") is False
        and cleanup.get("live_service_enable_attempted") is True
        and cleanup.get("live_service_disable_attempted") is True
        and cleanup.get("live_service_disable_proven_before_cleanup") is True
        and cleanup.get("live_service_disable_proven_after_cleanup") is True,
        "failed_v2_cleanup_evidence_mismatch",
    )
    require(
        sentinel.get("process_id") == FAILED_SUCCESSOR_V2_RUNTIME_PID
        and sentinel.get("phase") == "runtime_exited"
        and sentinel.get("installed") is True
        and sentinel.get("wrapper_identity_proven") is True
        and sentinel.get("root_create_order_call_count") == 0
        and sentinel.get("child_place_limit_order_call_count") == 0
        and sentinel.get("root_sdk_inflight") is False
        and sentinel.get("child_sdk_inflight") is False
        and sentinel.get("denied_call_count") == 0
        and sentinel.get("critical_failure") is False
        and sentinel.get("error") is None,
        "failed_v2_final_sentinel_mismatch",
    )
    require(
        parent_loss.get("parent_pid") == FAILED_SUCCESSOR_V2_PARENT_PID
        and parent_loss.get("live_service_disable_proven") is True
        and parent_loss.get("new_sdk_placements_denied") is True
        and parent_loss.get("sdk_quiescence_proven") is True
        and parent_loss.get("root_create_order_call_count") == 0
        and parent_loss.get("child_place_limit_order_call_count") == 0
        and parent_loss.get("denied_sdk_call_count") == 0
        and parent_loss.get("root_sdk_inflight_after_wait") is False
        and parent_loss.get("child_sdk_inflight_after_wait") is False
        and parent_loss.get("authoritative_active_order_read_proven") is True
        and parent_loss.get("authoritative_active_orders_before_cancel") == []
        and parent_loss.get("authoritative_active_orders_after_reconciliation")
        == []
        and parent_loss.get("authoritative_active_zero_after_reconciliation")
        is True
        and parent_loss.get("unknown_active_client_order_ids") == []
        and parent_loss.get("exact_active_client_order_ids") == []
        and parent_loss.get("transmitted_attempt_count") == 0
        and parent_loss.get("terminal_transmitted_attempt_count") == 0
        and parent_loss.get("all_transmitted_attempts_terminal") is True
        and parent_loss.get("exact_transmitted_attempt_states") == {}
        and parent_loss.get("critical_attempt_failures") == {}
        and parent_loss.get("operator_reconciliation_required") is False
        and parent_loss.get("automatic_cancel_retry_authorized") is False,
        "failed_v2_parent_loss_evidence_mismatch",
    )
    for payload, blocker in (
        (runtime_auth, "failed_v2_runtime_auth_identity_mismatch"),
        (runtime_auth_used, "failed_v2_runtime_auth_used_identity_mismatch"),
    ):
        require(
            payload.get("approval_id") == FAILED_SUCCESSOR_V2_APPROVAL_ID
            and payload.get("batch_id") == FAILED_SUCCESSOR_V2_BATCH_ID
            and payload.get("plan_sha256") == FAILED_SUCCESSOR_V2_PLAN_SHA256
            and payload.get("runner_sha256") == FAILED_SUCCESSOR_V2_RUNNER_SHA256
            and payload.get("parent_pid") == FAILED_SUCCESSOR_V2_PARENT_PID
            and payload.get("attempt_ledger_path")
            == str(FAILED_SUCCESSOR_V2_LEDGER_PATH),
            blocker,
        )
    return offline_failed_v2_binding_fixture()


