def prove_fresh_successor_plan_ids_absent(
    rest_client: Any,
    *,
    confirmed_plan: Mapping[str, Any],
    recovery_slot_5: Mapping[str, Any],
) -> dict[str, Any]:
    """Prove every fresh v13 slot-6-through-10 identity absent everywhere."""

    roots = [object_record(item) for item in list_value(confirmed_plan.get("roots"))]
    planned_ids = {
        str(value)
        for root in roots
        for value in (
            root.get("root_client_order_id"),
            root.get("child_client_order_id"),
        )
    }
    recovery_ids = {
        str(recovery_slot_5.get("root_client_order_id") or ""),
        str(recovery_slot_5.get("child_client_order_id") or ""),
    }
    require(
        len(roots) == SUCCESSOR_ROOT_ORDER_MAXIMUM
        and [root.get("slot") for root in roots] == list(range(6, 11))
        and len(planned_ids) == SUCCESSOR_ROOT_ORDER_MAXIMUM * 2
        and all(planned_ids)
        and len(recovery_ids) == 2
        and all(recovery_ids)
        and not planned_ids & recovery_ids,
        "successor_fresh_plan_ids_not_exact_disjoint",
    )
    local = prove_local_scope_with_historical_hidden_child(
        planned_client_order_ids=planned_ids,
        carried_root_plan=completed_slot_1_binding_fixture(),
        recovery_slot_5=recovery_slot_5,
    )
    rows, pagination = read_failed_v6_v7_order_catalog(rest_client)
    matches = [
        dict(row)
        for row in rows
        if str(row.get("client_order_id") or "") in planned_ids
    ]
    require(
        pagination.get("authoritative") is True
        and pagination.get("pagination_complete") is True
        and int(pagination.get("page_count") or 0) >= 1
        and pagination.get("order_count") == len(rows)
        and not matches,
        "successor_fresh_plan_ids_coinbase_absence_unproven",
    )
    require(
        local.get("planned_ids_absent_from_order_parent") is True
        and local.get("planned_ids_absent_from_stealth_orders") is True
        and local.get("planned_ids_absent_from_fill_ledger") is True
        and local.get("planned_ids_absent_from_order_match_audit") is True,
        "successor_fresh_plan_ids_local_absence_unproven",
    )
    return {
        "planned_client_order_ids": sorted(planned_ids),
        "planned_client_order_id_count": len(planned_ids),
        "coinbase_matching_orders": [],
        "coinbase_pagination": dict(pagination),
        "local_exact_absence": local,
        "fresh_read": True,
    }


def prove_stable_authoritative_active_zero(
    rest_client: Any,
    *,
    expected_portfolio_id: str,
) -> dict[str, Any]:
    """Require two stable exact-scope active-order reads returning zero."""

    first = read_authoritative_spot_nonterminal_orders(
        rest_client,
        expected_portfolio_id=expected_portfolio_id,
    )
    time.sleep(0.5)
    second = read_authoritative_spot_nonterminal_orders(
        rest_client,
        expected_portfolio_id=expected_portfolio_id,
    )
    require(
        first == second and not second,
        "authoritative_active_spot_zero_not_stable",
    )
    return {
        "first": first,
        "second": second,
        "authoritative_active_spot_order_count": 0,
        "stable_zero": True,
    }


def prove_local_scope_with_historical_hidden_child(
    *,
    planned_client_order_ids: set[str],
    carried_root_plan: Mapping[str, Any] | None = None,
    recovery_slot_2: Mapping[str, Any] | None = None,
    recovery_slot_3: Mapping[str, Any] | None = None,
    recovery_slot_5: Mapping[str, Any] | None = None,
    current_plan_in_progress_chain: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Allow only the exact prior FILLED root and wholly unsubmitted child.

    This is deliberately a read-only identity exception, not reusable cleanup
    authority. No command emitted by this runner may target either historical
    identifier.
    """

    immutable_historical_ids = {
        HISTORICAL_FILLED_ROOT_CLIENT_ORDER_ID,
        HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID,
    }
    carried_ids = (
        {CARRIED_ROOT_CLIENT_ORDER_ID, CARRIED_CHILD_CLIENT_ORDER_ID}
        if carried_root_plan is not None
        else set()
    )
    recovery_candidates = [
        item
        for item in (recovery_slot_2, recovery_slot_3, recovery_slot_5)
        if item is not None
    ]
    require(
        len(recovery_candidates) <= 1,
        "multiple_recovery_slots_not_authorized",
    )
    recovery_plan = recovery_slot_5 or recovery_slot_3 or recovery_slot_2
    recovery_root_id = (
        V12_SLOT_5_ROOT_CLIENT_ORDER_ID
        if recovery_slot_5 is not None
        else (
            V10_SLOT_3_ROOT_CLIENT_ORDER_ID
            if recovery_slot_3 is not None
            else V8_SLOT_2_ROOT_CLIENT_ORDER_ID
        )
    )
    recovery_child_id = (
        V12_SLOT_5_CHILD_CLIENT_ORDER_ID
        if recovery_slot_5 is not None
        else (
            V10_SLOT_3_CHILD_CLIENT_ORDER_ID
            if recovery_slot_3 is not None
            else V8_SLOT_2_CHILD_CLIENT_ORDER_ID
        )
    )
    recovery_ids = (
        {recovery_root_id, recovery_child_id}
        if recovery_plan is not None
        else set()
    )
    current_root_id = str(
        object_record(current_plan_in_progress_chain).get(
            "root_client_order_id"
        )
        or ""
    )
    current_child_id = str(
        object_record(current_plan_in_progress_chain).get(
            "child_client_order_id"
        )
        or ""
    )
    current_ids = (
        {current_root_id, current_child_id}
        if current_plan_in_progress_chain is not None
        else set()
    )
    require(
        current_plan_in_progress_chain is None or recovery_plan is None,
        "current_in_progress_and_recovery_not_authorized",
    )
    require(
        current_plan_in_progress_chain is None
        or (
            len(current_ids) == 2
            and all(current_ids)
            and not current_ids
            & (
                immutable_historical_ids
                | carried_ids
                | recovery_ids
                | planned_client_order_ids
            )
        ),
        "v12_in_progress_identity_overlap",
    )
    require(
        not (planned_client_order_ids - carried_ids - recovery_ids)
        & (immutable_historical_ids | carried_ids | recovery_ids),
        "batch_ids_overlap_historical_chain",
    )
    connection = psycopg2.connect(
        host=os.environ.get("COINBASE_DB_HOST", "127.0.0.1"),
        port=int(os.environ.get("COINBASE_DB_PORT", "5432")),
        dbname=os.environ.get("COINBASE_DB_NAME", "postgres"),
        user=os.environ.get("COINBASE_DB_USER", "postgres"),
        password=os.environ.get("COINBASE_DB_PASSWORD", "postgres"),
    )

    def row_dict(cursor: Any, row: Any) -> dict[str, Any]:
        require(row is not None, "historical_chain_row_missing")
        return dict(zip([column[0] for column in cursor.description], row))

    try:
        with connection.cursor() as cursor:
            cursor.execute(
                """SELECT client_order_id, parent_order_id, product_id, side,
                          size, status, ownership_provenance,
                          retail_portfolio_id, correlation_id, audit_id,
                          exchange_order_id
                     FROM order_parent
                    WHERE client_order_id = %s""",
                (HISTORICAL_FILLED_ROOT_CLIENT_ORDER_ID,),
            )
            root = row_dict(cursor, cursor.fetchone())
            cursor.execute(
                """SELECT client_order_id, parent_order_id, product_id, side,
                          size, status, ownership_provenance,
                          retail_portfolio_id, correlation_id, audit_id,
                          exchange_order_id
                     FROM order_parent
                    WHERE client_order_id = %s""",
                (HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID,),
            )
            child = row_dict(cursor, cursor.fetchone())
            cursor.execute(
                """SELECT stealth_order_id, parent_order_id, product_id, side,
                          total_size, remaining_size, revealed_size,
                          executed_size, status, revealed_orders,
                          last_placement_at, condition_first_met_at,
                          condition_confirmed_at, anchor_repricing_state_json
                     FROM stealth_orders
                    WHERE stealth_order_id = %s""",
                (HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID,),
            )
            stealth = row_dict(cursor, cursor.fetchone())
            carried_root: dict[str, Any] | None = None
            carried_child: dict[str, Any] | None = None
            carried_stealth: dict[str, Any] | None = None
            recovery_root: dict[str, Any] | None = None
            recovery_child: dict[str, Any] | None = None
            recovery_stealth: dict[str, Any] | None = None
            recovery_direct_child_ids: list[str] = []
            recovery_grandchild_ids: list[str] = []
            current_root: dict[str, Any] | None = None
            current_child: dict[str, Any] | None = None
            current_stealth: dict[str, Any] | None = None
            current_direct_child_ids: list[str] = []
            current_grandchild_ids: list[str] = []
            if carried_root_plan is not None:
                cursor.execute(
                    """SELECT client_order_id, parent_order_id, product_id, side,
                              size, status, ownership_provenance,
                              retail_portfolio_id, correlation_id, audit_id,
                              exchange_order_id
                         FROM order_parent
                        WHERE client_order_id = %s""",
                    (CARRIED_ROOT_CLIENT_ORDER_ID,),
                )
                carried_root = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT client_order_id, parent_order_id, product_id, side,
                              size, status, ownership_provenance,
                              retail_portfolio_id, correlation_id, audit_id,
                              exchange_order_id
                         FROM order_parent
                        WHERE client_order_id = %s""",
                    (CARRIED_CHILD_CLIENT_ORDER_ID,),
                )
                carried_child = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT stealth_order_id, parent_order_id, product_id, side,
                              total_size, remaining_size, revealed_size,
                              executed_size, status, revealed_orders,
                              last_placement_at, condition_first_met_at,
                              condition_confirmed_at, anchor_repricing_state_json,
                              reveal_condition_type, reveal_condition_json,
                              reason
                         FROM stealth_orders
                        WHERE stealth_order_id = %s""",
                    (CARRIED_CHILD_CLIENT_ORDER_ID,),
                )
                carried_stealth = row_dict(cursor, cursor.fetchone())
            if recovery_plan is not None:
                cursor.execute(
                    """SELECT client_order_id, parent_order_id, product_id, side,
                              size, status, ownership_provenance,
                              retail_portfolio_id, correlation_id, audit_id,
                              exchange_order_id
                         FROM order_parent
                        WHERE client_order_id = %s""",
                    (recovery_root_id,),
                )
                recovery_root = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT client_order_id, parent_order_id, product_id, side,
                              size, status, ownership_provenance,
                              retail_portfolio_id, correlation_id, audit_id,
                              exchange_order_id
                         FROM order_parent
                        WHERE client_order_id = %s""",
                    (recovery_child_id,),
                )
                recovery_child = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT stealth_order_id, parent_order_id, product_id, side,
                              total_size, remaining_size, revealed_size,
                              executed_size, status, revealed_orders,
                              last_placement_at, condition_first_met_at,
                              condition_confirmed_at, anchor_repricing_state_json
                         FROM stealth_orders
                        WHERE stealth_order_id = %s""",
                    (recovery_child_id,),
                )
                recovery_stealth = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT client_order_id
                         FROM order_parent
                        WHERE parent_order_id = %s
                        ORDER BY client_order_id""",
                    (recovery_root_id,),
                )
                recovery_direct_child_ids = [
                    str(row[0]) for row in cursor.fetchall()
                ]
                cursor.execute(
                    """SELECT client_order_id
                         FROM order_parent
                        WHERE parent_order_id = %s
                        ORDER BY client_order_id""",
                    (recovery_child_id,),
                )
                recovery_grandchild_ids = [
                    str(row[0]) for row in cursor.fetchall()
                ]
            if current_plan_in_progress_chain is not None:
                cursor.execute(
                    """SELECT client_order_id, parent_order_id, product_id, side,
                              size, status, ownership_provenance,
                              retail_portfolio_id, correlation_id, audit_id,
                              exchange_order_id
                         FROM order_parent
                        WHERE client_order_id = %s""",
                    (current_root_id,),
                )
                current_root = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT client_order_id, parent_order_id, product_id, side,
                              size, status, ownership_provenance,
                              retail_portfolio_id, correlation_id, audit_id,
                              exchange_order_id
                         FROM order_parent
                        WHERE client_order_id = %s""",
                    (current_child_id,),
                )
                current_child = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT stealth_order_id, parent_order_id, product_id, side,
                              total_size, remaining_size, revealed_size,
                              executed_size, status, revealed_orders,
                              last_placement_at, condition_first_met_at,
                              condition_confirmed_at, anchor_repricing_state_json
                         FROM stealth_orders
                        WHERE stealth_order_id = %s""",
                    (current_child_id,),
                )
                current_stealth = row_dict(cursor, cursor.fetchone())
                cursor.execute(
                    """SELECT client_order_id
                         FROM order_parent
                        WHERE parent_order_id = %s
                        ORDER BY client_order_id""",
                    (current_root_id,),
                )
                current_direct_child_ids = [
                    str(row[0]) for row in cursor.fetchall()
                ]
                cursor.execute(
                    """SELECT client_order_id
                         FROM order_parent
                        WHERE parent_order_id = %s
                        ORDER BY client_order_id""",
                    (current_child_id,),
                )
                current_grandchild_ids = [
                    str(row[0]) for row in cursor.fetchall()
                ]
            cursor.execute(
                """SELECT client_order_id
                     FROM order_parent
                    WHERE upper(status) NOT IN
                          ('FILLED','CANCELLED','CANCELED','FAILED',
                           'REJECTED','EXPIRED')
                    ORDER BY client_order_id"""
            )
            nonterminal_parents = [str(row[0]) for row in cursor.fetchall()]
            cursor.execute(
                """SELECT stealth_order_id
                     FROM stealth_orders
                    WHERE upper(status) NOT IN
                          ('EXECUTED','FILLED','CANCELLED','CANCELED','FAILED',
                           'REJECTED','EXPIRED')
                    ORDER BY stealth_order_id"""
            )
            nonterminal_stealth = [str(row[0]) for row in cursor.fetchall()]
            planned_parent_collisions: list[str] = []
            planned_stealth_collisions: list[str] = []
            planned_fill_collisions: list[str] = []
            planned_match_audit_collisions: list[str] = []
            if planned_client_order_ids:
                planned_ids = sorted(planned_client_order_ids)
                cursor.execute(
                    """SELECT client_order_id
                         FROM order_parent
                        WHERE client_order_id = ANY(%s)
                        ORDER BY client_order_id""",
                    (planned_ids,),
                )
                planned_parent_collisions = [
                    str(row[0]) for row in cursor.fetchall()
                ]
                cursor.execute(
                    """SELECT stealth_order_id
                         FROM stealth_orders
                        WHERE stealth_order_id::text = ANY(%s)
                        ORDER BY stealth_order_id""",
                    (planned_ids,),
                )
                planned_stealth_collisions = [
                    str(row[0]) for row in cursor.fetchall()
                ]
                cursor.execute(
                    """SELECT DISTINCT client_order_id
                         FROM fill_ledger
                        WHERE client_order_id = ANY(%s)
                        ORDER BY client_order_id""",
                    (planned_ids,),
                )
                planned_fill_collisions = [
                    str(row[0]) for row in cursor.fetchall()
                ]
                cursor.execute(
                    """SELECT DISTINCT client_order_id
                         FROM order_match_audit
                        WHERE client_order_id = ANY(%s)
                        ORDER BY client_order_id""",
                    (planned_ids,),
                )
                planned_match_audit_collisions = [
                    str(row[0]) for row in cursor.fetchall()
                ]
    finally:
        connection.close()

    require(
        root.get("client_order_id")
        == HISTORICAL_FILLED_ROOT_CLIENT_ORDER_ID,
        "historical_root_identity_mismatch",
    )
    require(not root.get("parent_order_id"), "historical_root_not_flat")
    require(
        root.get("product_id") == PRODUCT_ID
        and str(root.get("side") or "").upper() == "BUY"
        and str(root.get("status") or "").upper() == "FILLED"
        and root.get("ownership_provenance") == "ADMIN_MANUAL_ROOT"
        and bool(str(root.get("exchange_order_id") or "")),
        "historical_root_evidence_mismatch",
    )
    require(
        deterministic_child_client_order_id(
            HISTORICAL_FILLED_ROOT_CLIENT_ORDER_ID
        )
        == HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID,
        "historical_child_not_deterministic",
    )
    require(
        child.get("client_order_id")
        == HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID
        and str(child.get("parent_order_id") or "")
        == HISTORICAL_FILLED_ROOT_CLIENT_ORDER_ID
        and child.get("product_id") == PRODUCT_ID
        and str(child.get("side") or "").upper() == "SELL"
        and str(child.get("status") or "").upper() == "PENDING"
        and child.get("ownership_provenance") == "ADMIN_FILL_FOLLOW_UP"
        and not child.get("exchange_order_id"),
        "historical_child_tracking_evidence_mismatch",
    )
    require(
        str(root.get("retail_portfolio_id") or "")
        == str(child.get("retail_portfolio_id") or "")
        and bool(str(root.get("retail_portfolio_id") or "")),
        "historical_chain_portfolio_mismatch",
    )
    require(
        str(root.get("correlation_id") or "")
        == str(child.get("correlation_id") or "")
        and bool(str(root.get("correlation_id") or "")),
        "historical_chain_correlation_mismatch",
    )
    require(
        str(root.get("audit_id") or "")
        == str(child.get("audit_id") or "")
        and bool(str(root.get("audit_id") or "")),
        "historical_chain_audit_mismatch",
    )
    anchor_state = object_record(stealth.get("anchor_repricing_state_json"))
    revealed_orders = list_value(stealth.get("revealed_orders"))
    require(
        str(stealth.get("stealth_order_id") or "")
        == HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID
        and str(stealth.get("parent_order_id") or "")
        == HISTORICAL_FILLED_ROOT_CLIENT_ORDER_ID
        and stealth.get("product_id") == PRODUCT_ID
        and str(stealth.get("side") or "").upper() == "SELL"
        and str(stealth.get("status") or "").upper() == "HIDDEN",
        "historical_stealth_child_identity_mismatch",
    )
    total_size = Decimal(str(stealth.get("total_size") or "0"))
    require(
        total_size > 0
        and total_size == Decimal(str(stealth.get("remaining_size") or "0"))
        and Decimal(str(stealth.get("revealed_size") or "0")) == 0
        and Decimal(str(stealth.get("executed_size") or "0")) == 0
        and total_size == Decimal(str(child.get("size") or "0"))
        and not revealed_orders
        and stealth.get("last_placement_at") is None
        and not anchor_state.get("active_placement_client_order_id")
        and not anchor_state.get("active_exchange_order_id")
        and not anchor_state.get(
            "controlled_admin_first_child_reveal_preparation"
        ),
        "historical_stealth_child_not_wholly_unsubmitted",
    )
    carried_scope: dict[str, Any] | None = None
    carried_nonterminal = False
    if carried_root_plan is not None:
        require(
            carried_root is not None
            and carried_child is not None
            and carried_stealth is not None,
            "carried_chain_row_missing",
        )
        require(
            carried_root.get("client_order_id")
            == CARRIED_ROOT_CLIENT_ORDER_ID
            and not carried_root.get("parent_order_id")
            and carried_root.get("product_id") == PRODUCT_ID
            and str(carried_root.get("side") or "").upper() == "BUY"
            and str(carried_root.get("status") or "").upper() == "FILLED"
            and carried_root.get("ownership_provenance")
            == "ADMIN_MANUAL_ROOT"
            and carried_root.get("exchange_order_id")
            == CARRIED_ROOT_EXCHANGE_ORDER_ID
            and carried_root.get("retail_portfolio_id")
            == offline_predecessor_binding_fixture()["portfolio_id"]
            and Decimal(str(carried_root.get("size") or "0"))
            == CARRIED_ROOT_FILLED_SIZE
            and carried_root.get("correlation_id")
            == CARRIED_ROOT_CORRELATION_ID
            and carried_root.get("audit_id")
            == CARRIED_ROOT_ADMISSION_AUDIT_ID,
            "carried_root_evidence_mismatch",
        )
        require(
            deterministic_child_client_order_id(CARRIED_ROOT_CLIENT_ORDER_ID)
            == CARRIED_CHILD_CLIENT_ORDER_ID,
            "carried_child_not_deterministic",
        )
        child_status = str(carried_child.get("status") or "").upper()
        stealth_status = str(carried_stealth.get("status") or "").upper()
        carried_nonterminal = child_status not in TERMINAL_STATUSES
        require(
            carried_child.get("client_order_id")
            == CARRIED_CHILD_CLIENT_ORDER_ID
            and str(carried_child.get("parent_order_id") or "")
            == CARRIED_ROOT_CLIENT_ORDER_ID
            and carried_child.get("product_id") == PRODUCT_ID
            and str(carried_child.get("side") or "").upper() == "SELL"
            and carried_child.get("ownership_provenance")
            == "ADMIN_FILL_FOLLOW_UP"
            and carried_child.get("retail_portfolio_id")
            == carried_root.get("retail_portfolio_id")
            and carried_child.get("correlation_id")
            == carried_root.get("correlation_id")
            and carried_child.get("audit_id") == carried_root.get("audit_id"),
            "carried_child_tracking_evidence_mismatch",
        )
        require(
            Decimal(str(carried_child.get("size") or "0"))
            == CARRIED_ROOT_FILLED_SIZE,
            "carried_child_size_mismatch",
        )
        carried_completion = validate_completed_slot_1_local_state(
            root_row=carried_root,
            tracking_row=carried_child,
            stealth_row=carried_stealth,
        )
        carried_anchor = object_record(
            carried_stealth.get("anchor_repricing_state_json")
        )
        carried_revealed = list_value(carried_stealth.get("revealed_orders"))
        carried_total = Decimal(str(carried_stealth.get("total_size") or "0"))
        carried_executed = Decimal(
            str(carried_stealth.get("executed_size") or "0")
        )
        require(
            carried_stealth.get("stealth_order_id")
            == CARRIED_CHILD_CLIENT_ORDER_ID
            and str(carried_stealth.get("parent_order_id") or "")
            == CARRIED_ROOT_CLIENT_ORDER_ID
            and carried_stealth.get("product_id") == PRODUCT_ID
            and str(carried_stealth.get("side") or "").upper() == "SELL"
            and carried_total == CARRIED_ROOT_FILLED_SIZE
            and carried_executed == 0,
            "carried_stealth_identity_mismatch",
        )
        if carried_nonterminal:
            require(
                child_status in {"PENDING", "HIDDEN", "TRIGGERED"}
                and stealth_status in {"PENDING", "HIDDEN", "TRIGGERED"}
                and not carried_child.get("exchange_order_id")
                and carried_total
                == Decimal(str(carried_stealth.get("remaining_size") or "0"))
                and Decimal(str(carried_stealth.get("revealed_size") or "0"))
                == 0
                and not carried_revealed
                and carried_stealth.get("last_placement_at") is None
                and not carried_anchor.get("active_placement_client_order_id")
                and not carried_anchor.get("active_exchange_order_id")
                and not carried_anchor.get(
                    "controlled_admin_first_child_reveal_preparation"
                ),
                "carried_child_not_wholly_unsubmitted",
            )
            # Condition timestamps may be set by bridge evaluation before the
            # controlled route atomically clears them. They are not placement
            # evidence and must not broaden authority.
        else:
            require(
                child_status in {"CANCELLED", "CANCELED"}
                and stealth_status in {"CANCELLED", "CANCELED"}
                and carried_executed == 0,
                "carried_child_not_zero_fill_cancelled",
            )
        require(
            not carried_nonterminal,
            "completed_slot_1_child_not_terminal",
        )
        carried_scope = {
            "root_client_order_id": CARRIED_ROOT_CLIENT_ORDER_ID,
            "child_client_order_id": CARRIED_CHILD_CLIENT_ORDER_ID,
            "root_status": "FILLED",
            "child_parent_status": child_status,
            "child_stealth_status": stealth_status,
            "child_wholly_unsubmitted": carried_nonterminal,
            "condition_timestamps_do_not_authorize_placement": True,
            "root_placement_authorized": False,
            "completion_proof": carried_completion,
        }
    recovery_scope: dict[str, Any] | None = None
    recovery_nonterminal = False
    if recovery_plan is not None:
        is_v13_recovery = recovery_slot_5 is not None
        is_v11_recovery = recovery_slot_3 is not None
        expected_slot = 5 if is_v13_recovery else (3 if is_v11_recovery else 2)
        expected_exchange_id = (
            V12_SLOT_5_ROOT_EXCHANGE_ORDER_ID
            if is_v13_recovery
            else (
                V10_SLOT_3_ROOT_EXCHANGE_ORDER_ID
                if is_v11_recovery
                else V8_SLOT_2_ROOT_EXCHANGE_ORDER_ID
            )
        )
        expected_size = (
            V12_SLOT_5_ROOT_FILLED_SIZE
            if is_v13_recovery
            else (
                V10_SLOT_3_ROOT_FILLED_SIZE
                if is_v11_recovery
                else V8_SLOT_2_ROOT_FILLED_SIZE
            )
        )
        expected_correlation_id = (
            V12_SLOT_5_ROOT_CORRELATION_ID
            if is_v13_recovery
            else (
                V10_SLOT_3_ROOT_CORRELATION_ID
                if is_v11_recovery
                else V8_SLOT_2_ROOT_CORRELATION_ID
            )
        )
        expected_audit_id = (
            V12_SLOT_5_ROOT_ADMISSION_AUDIT_ID
            if is_v13_recovery
            else (
                V10_SLOT_3_ROOT_ADMISSION_AUDIT_ID
                if is_v11_recovery
                else V8_SLOT_2_ROOT_ADMISSION_AUDIT_ID
            )
        )
        require(
            recovery_root is not None
            and recovery_child is not None
            and recovery_stealth is not None,
            f"recovery_slot_{expected_slot}_chain_row_missing",
        )
        require(
            recovery_plan.get("slot") == expected_slot
            and recovery_plan.get("root_placement_authorized") is False
            and recovery_plan.get("child_recovery_authorized") is True
            and recovery_plan.get("root_client_order_id") == recovery_root_id
            and recovery_plan.get("child_client_order_id") == recovery_child_id,
            f"recovery_slot_{expected_slot}_plan_scope_mismatch",
        )
        if is_v13_recovery:
            require(
                recovery_plan.get("prior_root_attempt_tuple_sha256")
                == V12_SLOT_5_ROOT_TUPLE_SHA256
                and recovery_plan.get("prior_child_sdk_call_occurred") is False,
                "recovery_slot_5_v12_attempt_scope_mismatch",
            )
        elif is_v11_recovery:
            require(
                recovery_plan.get("prior_child_attempt_tuple_sha256")
                == V10_SLOT_3_CHILD_TUPLE_SHA256
                and recovery_plan.get("prior_child_sdk_call_occurred") is False,
                "recovery_slot_3_v10_attempt_scope_mismatch",
            )
        else:
            require(
                recovery_plan.get("controlled_prior_preparation_sha256")
                == V8_SLOT_2_PRIOR_PREPARATION_SHA256,
                "recovery_slot_2_prior_preparation_mismatch",
            )
        require(
            recovery_direct_child_ids == [recovery_child_id]
            and not recovery_grandchild_ids,
            f"recovery_slot_{expected_slot}_flat_hierarchy_mismatch",
        )
        require(
            recovery_root.get("client_order_id") == recovery_root_id
            and not recovery_root.get("parent_order_id")
            and recovery_root.get("product_id") == PRODUCT_ID
            and str(recovery_root.get("side") or "").upper() == "BUY"
            and str(recovery_root.get("status") or "").upper() == "FILLED"
            and recovery_root.get("ownership_provenance")
            == "ADMIN_MANUAL_ROOT"
            and recovery_root.get("retail_portfolio_id") == TEST_PORTFOLIO_ID
            and recovery_root.get("exchange_order_id") == expected_exchange_id
            and Decimal(str(recovery_root.get("size") or "0")) == expected_size
            and recovery_root.get("correlation_id") == expected_correlation_id
            and recovery_root.get("audit_id") == expected_audit_id,
            f"recovery_slot_{expected_slot}_root_local_state_mismatch",
        )
        recovery_child_status = str(
            recovery_child.get("status") or ""
        ).upper()
        recovery_stealth_status = str(
            recovery_stealth.get("status") or ""
        ).upper()
        recovery_nonterminal = recovery_child_status not in TERMINAL_STATUSES
        require(
            recovery_child.get("client_order_id") == recovery_child_id
            and str(recovery_child.get("parent_order_id") or "")
            == recovery_root_id
            and recovery_child.get("product_id") == PRODUCT_ID
            and str(recovery_child.get("side") or "").upper() == "SELL"
            and recovery_child.get("ownership_provenance")
            == "ADMIN_FILL_FOLLOW_UP"
            and recovery_child.get("retail_portfolio_id") == TEST_PORTFOLIO_ID
            and recovery_child.get("correlation_id") == expected_correlation_id
            and recovery_child.get("audit_id") == expected_audit_id
            and Decimal(str(recovery_child.get("size") or "0")) == expected_size,
            f"recovery_slot_{expected_slot}_child_local_state_mismatch",
        )
        recovery_anchor = object_record(
            recovery_stealth.get("anchor_repricing_state_json")
        )
        recovery_current_preparation = object_record(
            recovery_anchor.get(
                "controlled_admin_first_child_reveal_preparation"
            )
        )
        recovery_history = list_value(
            recovery_anchor.get(
                "controlled_admin_first_child_reveal_preparation_history"
            )
        )
        require(
            recovery_stealth.get("stealth_order_id") == recovery_child_id
            and str(recovery_stealth.get("parent_order_id") or "")
            == recovery_root_id
            and recovery_stealth.get("product_id") == PRODUCT_ID
            and str(recovery_stealth.get("side") or "").upper() == "SELL"
            and Decimal(str(recovery_stealth.get("total_size") or "0"))
            == expected_size
            and Decimal(str(recovery_stealth.get("executed_size") or "0"))
            == 0
            and not recovery_anchor.get("active_placement_client_order_id")
            and not recovery_anchor.get("active_exchange_order_id"),
            f"recovery_slot_{expected_slot}_stealth_local_state_mismatch",
        )
        if recovery_nonterminal:
            if is_v13_recovery:
                preparation_exact = bool(
                    not recovery_current_preparation and not recovery_history
                )
                recovery_phase = "v12_unsubmitted_hidden"
            elif is_v11_recovery:
                preparation_exact = bool(
                    not recovery_current_preparation and not recovery_history
                )
                recovery_phase = "v10_unsubmitted_hidden"
            else:
                prior_preparation_exact = bool(
                    _canonical_json_sha256(recovery_current_preparation)
                    == V8_SLOT_2_PRIOR_PREPARATION_SHA256
                    and not recovery_history
                )
                superseded_preparation_exact = bool(
                    recovery_plan.get("recovery_batch_id")
                    and recovery_current_preparation.get("batch_id")
                    == recovery_plan.get("recovery_batch_id")
                    and recovery_current_preparation.get(
                        "supersedes_preparation_sha256"
                    )
                    == V8_SLOT_2_PRIOR_PREPARATION_SHA256
                    and len(recovery_history) == 1
                    and object_record(recovery_history[0]).get(
                        "preparation_sha256"
                    )
                    == V8_SLOT_2_PRIOR_PREPARATION_SHA256
                )
                preparation_exact = bool(
                    prior_preparation_exact or superseded_preparation_exact
                )
                recovery_phase = (
                    "v8_prepared_hidden"
                    if prior_preparation_exact
                    else "v10_superseded_preplacement_hidden"
                )
            require(
                recovery_child_status == "PENDING"
                and recovery_stealth_status == "HIDDEN"
                and not recovery_child.get("exchange_order_id")
                and Decimal(str(recovery_stealth.get("remaining_size") or "0"))
                == expected_size
                and Decimal(str(recovery_stealth.get("revealed_size") or "0"))
                == 0
                and not list_value(recovery_stealth.get("revealed_orders"))
                and recovery_stealth.get("last_placement_at") is None
                and preparation_exact,
                f"recovery_slot_{expected_slot}_preexchange_state_mismatch",
            )
        else:
            if is_v13_recovery:
                preparation_exact = bool(
                    recovery_current_preparation.get("batch_id")
                    == recovery_plan.get("recovery_batch_id")
                    and recovery_current_preparation.get("batch_slot") == 5
                    and not recovery_history
                )
                recovery_phase = "v13_recovered_zero_fill_cancelled"
            elif is_v11_recovery:
                preparation_exact = bool(
                    recovery_current_preparation.get("batch_id")
                    == recovery_plan.get("recovery_batch_id")
                    and recovery_current_preparation.get("batch_slot") == 3
                    and not recovery_history
                )
                recovery_phase = "v11_recovered_zero_fill_cancelled"
            else:
                preparation_exact = bool(
                    recovery_current_preparation.get(
                        "supersedes_preparation_sha256"
                    )
                    == V8_SLOT_2_PRIOR_PREPARATION_SHA256
                    and len(recovery_history) == 1
                    and object_record(recovery_history[0]).get(
                        "preparation_sha256"
                    )
                    == V8_SLOT_2_PRIOR_PREPARATION_SHA256
                )
                recovery_phase = "v10_recovered_zero_fill_cancelled"
            require(
                recovery_child_status in {"CANCELLED", "CANCELED"}
                and recovery_stealth_status in {"CANCELLED", "CANCELED"}
                and bool(str(recovery_child.get("exchange_order_id") or ""))
                and preparation_exact,
                f"recovery_slot_{expected_slot}_zero_fill_cancelled_mismatch",
            )
        recovery_scope = {
            "slot": expected_slot,
            "root_client_order_id": recovery_root_id,
            "child_client_order_id": recovery_child_id,
            "root_exchange_order_id": expected_exchange_id,
            "root_status": "FILLED",
            "child_parent_status": recovery_child_status,
            "child_stealth_status": recovery_stealth_status,
            "child_executed_size": "0",
            "phase": recovery_phase,
            "root_placement_authorized": False,
            "sql_mutation_performed": False,
        }
        if recovery_slot_2 is not None:
            recovery_scope["prior_preparation_sha256"] = (
                V8_SLOT_2_PRIOR_PREPARATION_SHA256
            )
    current_in_progress_scope: dict[str, Any] | None = None
    if current_plan_in_progress_chain is not None:
        require(
            current_root is not None
            and current_child is not None
            and current_stealth is not None,
            "v12_in_progress_chain_row_missing",
        )
        current_in_progress_scope = validate_v12_in_progress_local_chain(
            scope=current_plan_in_progress_chain,
            root_row=current_root,
            child_row=current_child,
            stealth_row=current_stealth,
            direct_child_client_order_ids=current_direct_child_ids,
            grandchild_client_order_ids=current_grandchild_ids,
        )
    expected_nonterminal = [HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID]
    if carried_nonterminal:
        expected_nonterminal.append(CARRIED_CHILD_CLIENT_ORDER_ID)
    if recovery_nonterminal:
        expected_nonterminal.append(recovery_child_id)
    if current_in_progress_scope is not None:
        expected_nonterminal.append(current_child_id)
    expected_nonterminal.sort()
    require(
        nonterminal_parents == expected_nonterminal,
        f"unrelated_local_nonterminal_parent_present:{nonterminal_parents}",
    )
    require(
        nonterminal_stealth == expected_nonterminal,
        f"unrelated_local_nonterminal_stealth_present:{nonterminal_stealth}",
    )
    require(
        not planned_parent_collisions,
        f"planned_client_order_ids_already_in_order_parent:{planned_parent_collisions}",
    )
    require(
        not planned_stealth_collisions,
        f"planned_client_order_ids_already_in_stealth_orders:{planned_stealth_collisions}",
    )
    require(
        not planned_fill_collisions,
        f"planned_client_order_ids_already_in_fill_ledger:{planned_fill_collisions}",
    )
    require(
        not planned_match_audit_collisions,
        f"planned_client_order_ids_already_in_order_match_audit:{planned_match_audit_collisions}",
    )
    return {
        "historical_root_client_order_id": (
            HISTORICAL_FILLED_ROOT_CLIENT_ORDER_ID
        ),
        "historical_child_client_order_id": (
            HISTORICAL_HIDDEN_CHILD_CLIENT_ORDER_ID
        ),
        "historical_root_status": "FILLED",
        "historical_child_parent_status": "PENDING",
        "historical_child_stealth_status": "HIDDEN",
        "historical_child_exchange_order_id": None,
        "historical_child_revealed_order_count": 0,
        "historical_child_active_placement": False,
        "exception_is_read_only": True,
        "planned_ids_disjoint": True,
        "planned_ids_absent_from_order_parent": True,
        "planned_ids_absent_from_stealth_orders": True,
        "planned_ids_absent_from_fill_ledger": True,
        "planned_ids_absent_from_order_match_audit": True,
        "carried_chain": carried_scope,
        "recovery_slot_2_chain": (
            recovery_scope if recovery_slot_2 is not None else None
        ),
        "recovery_slot_3_chain": (
            recovery_scope if recovery_slot_3 is not None else None
        ),
        "recovery_slot_5_chain": (
            recovery_scope if recovery_slot_5 is not None else None
        ),
        "current_plan_in_progress_chain": current_in_progress_scope,
    }


def validate_runner_commit_topology(
    *,
    production_commit: str,
    head_commit: str,
    head_parents: Sequence[str],
    changed_paths: Sequence[str],
    runner_path: str,
    committed_runner_sha256: str,
    working_runner_sha256: str,
    additional_allowed_paths: Sequence[str] = (),
) -> dict[str, Any]:
    """Require one exact scoped commit directly atop the production tree."""

    require(
        len(production_commit) == 40
        and all(
            character in "0123456789abcdef"
            for character in production_commit
        ),
        "backend_production_commit_not_patched",
    )
    require(
        len(head_commit) == 40
        and all(character in "0123456789abcdef" for character in head_commit),
        "runner_head_commit_invalid",
    )
    require(
        head_commit != production_commit,
        "runner_commit_missing_above_production_commit",
    )
    require(
        list(head_parents) == [production_commit],
        "runner_commit_not_directly_above_production_commit",
    )
    expected_paths = {runner_path, *additional_allowed_paths}
    require(
        len(expected_paths) == 1 + len(additional_allowed_paths)
        and set(changed_paths) == expected_paths
        and len(changed_paths) == len(expected_paths),
        "runner_commit_contains_non_runner_paths",
    )
    require(
        len(committed_runner_sha256) == 64
        and committed_runner_sha256 == working_runner_sha256,
        "committed_runner_bytes_mismatch",
    )
    return {
        "production_commit": production_commit,
        "runner_commit": head_commit,
        "runner_commit_parent": production_commit,
        "runner_path": runner_path,
        "additional_allowed_paths": list(additional_allowed_paths),
        "runner_sha256": working_runner_sha256,
        "runner_only_commit_proven": not additional_allowed_paths,
        "scoped_commit_proven": True,
    }


def require_failed_successor_commit_binding() -> dict[str, Any]:
    """Bind v1's recorded runner SHA to its runner-only Git commit."""

    require(
        FAILED_SUCCESSOR_V2_PRODUCTION_PARENT_COMMIT
        == FAILED_SUCCESSOR_V1_RUNNER_COMMIT,
        "failed_successor_v1_not_v2_production_parent",
    )
    runner_relative_path = (
        Path(__file__).resolve().relative_to(ROOT).as_posix()
    )
    parent_record = subprocess.check_output(
        [
            "git",
            "rev-list",
            "--parents",
            "-n",
            "1",
            FAILED_SUCCESSOR_V1_RUNNER_COMMIT,
        ],
        cwd=ROOT,
        text=True,
    ).strip().split()
    changed_paths = subprocess.check_output(
        [
            "git",
            "diff-tree",
            "--no-commit-id",
            "--name-only",
            "-r",
            FAILED_SUCCESSOR_V1_RUNNER_COMMIT,
        ],
        cwd=ROOT,
        text=True,
    ).splitlines()
    committed_runner_bytes = subprocess.check_output(
        [
            "git",
            "show",
            f"{FAILED_SUCCESSOR_V1_RUNNER_COMMIT}:{runner_relative_path}",
        ],
        cwd=ROOT,
    )
    committed_runner_sha256 = hashlib.sha256(
        committed_runner_bytes
    ).hexdigest()
    require(
        committed_runner_sha256 == FAILED_SUCCESSOR_V1_RUNNER_SHA256,
        "failed_successor_committed_runner_hash_mismatch",
    )
    return validate_runner_commit_topology(
        production_commit=FAILED_SUCCESSOR_V1_PRODUCTION_PARENT_COMMIT,
        head_commit=FAILED_SUCCESSOR_V1_RUNNER_COMMIT,
        head_parents=parent_record[1:],
        changed_paths=changed_paths,
        runner_path=runner_relative_path,
        committed_runner_sha256=committed_runner_sha256,
        working_runner_sha256=committed_runner_sha256,
    )


